function bikePhotoSlug(key) { return String(key).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, ""); }


/* ===== Конструктив запуска: кикстартер и электростартер =====
   Не на всех моторах есть кик (YBS300 / LX176MN, PR300, NB300, NC300 — только электростартер) и не на всех — стартер.
   Симптомы, причины, проверки, инструкции и запчасти про кик показываем только там, где кик есть; про стартер —
   только где есть электростартер. Признаки kick / estart — в groups мотора (по полю start); владелец может
   поменять запуск у своего экземпляра в «Настроить» (cu.start). Замечание механика: «у 176MN кика нет вовсе,
   а сайт предлагает „проскальзывает кикстартер“». */
(function () {
  /* исправления по проверке (магазины запчастей, характеристики продавцов) */
  ["YBS300", "YBS300G2"].forEach(function (id) { if (ENGINES[id]) ENGINES[id].start = "Электро"; }); // «Система запуска: электростартер», кика нет
  if (ENGINES.NC250) ENGINES.NC250.start = "Электро + кик";   // у ZS177MM есть вал и шестерня кикстартера
  if (ENGINES.CBS300) ENGINES.CBS300.start = "Электро + кик"; // ZS174MN-3 — электро и кик (у NB300 / ZS174MN-5 кика нет)
  Object.keys(ENGINES).forEach(function (id) { startTags(ENGINES[id]); });
  /* кик — только где он есть; стартер — только где есть электростартер */
  var pneed = { kick: "kick", kickkit: "kick", starter: "estart", sprag: "estart", starterrelay: "estart" };
  PARTS.forEach(function (p) { if (pneed[p.kind]) p.need = pneed[p.kind]; });
  /* слабые места про кик у моторов без кика — убрать */
  Object.keys(ENGINES).forEach(function (id) {
    var e = ENGINES[id];
    if (e.groups.indexOf("kick") < 0 && e.issues) e.issues = e.issues.filter(function (x) { return !/кикстарт|кик\b/i.test(x.t + " " + (x.fix || "")); });
  });
})();
/* признаки запуска по полю start: «Электро + кик» → kick, estart; «Кик (у части — электро)» → оба (не прячем лишнего) */
function startTags(e) {
  var s = String(e.start || "");
  e.groups = (e.groups || []).filter(function (g) { return g !== "kick" && g !== "estart"; });
  if (/кик/i.test(s)) e.groups.push("kick");
  if (/электро|стартер/i.test(s)) e.groups.push("estart");
  return e;
}

/* ===== Свечи: исправления по магазинам и дилерам (жалоба: «свечи не те на некоторых моделях») =====
   PR300 (ZS175FMN и родня) — NGK DR8EA (Regulmoto: «DR8EA (ZS172, PR300)»); питбайки YX140 / YX150 / YX160 — A7TC = NGK C7HSA
   («A7TC для YX125, YX140, YX160»); Zongshen 190 (ZS1P62YML-2, W190) — NGK CR8E / CPR8EA-9 (10 мм); Loncin YBS300 —
   Torch B8RC (pitland, motoprostore: «B8RC YBS300 Loncin»). Свечи-запчасти пересобираем,
   чтобы в «Запчастях» и в ТО была та же свеча, что в паспорте. */
(function () {
  function fixSpark(id, spark, gap) {
    var e = ENGINES[id];
    if (!e) return;
    e.spark = spark;
    if (gap) e.gap = gap;
    PARTS.forEach(function (p) { if (p.kind === "spark" && p.fit && p.fit.indexOf(id) >= 0 && p.id !== id + "-spark") p.fit = p.fit.filter(function (f) { return f !== id; }); });
    var mine = PARTS.find(function (p) { return p.id === id + "-spark"; });
    var name = "Свеча " + spark.split(" (")[0].split(" /")[0];
    if (mine) mine.name = name;
    else { var p = P(id + "-spark", name, 600, "Расходники", "spark", [id]); p.info = "Под " + e.code; PARTS.unshift(p); }
  }
  ["PR300", "FIXCN_PR300PRO", "FIXCN_PR300_5", "FIXCN_CB300RL_6"].forEach(function (id) { fixSpark(id, "NGK DR8EA", "0.6–0.7 мм"); });
  ["YX140", "1P60FMK"].forEach(function (id) { fixSpark(id, "A7TC (NGK C7HSA)", "0.6–0.7 мм"); });
  fixSpark("Z190", "NGK CR8E (CPR8EA-9)", "0.7–0.8 мм");
  /* YBS300 (Loncin LX176MN): в комплекте и у дилеров — Torch B8RC (= NGK CR8E: M10×1, резьба 19 мм, ключ 16) */
  ["YBS300", "YBS300G2"].forEach(function (id) { fixSpark(id, "Torch B8RC (NGK CR8E)", "0.7–0.8 мм"); });
})();
/* ===== Точные значения вместо «по мануалу» (часть 1): свечи — по каталогу NGK 2025–2026 для мотоциклов,
   клапаны — по руководствам владельца (Benelli TRK 251, Imperiale 400, Zontes ZT310-T) и мануалу Kawasaki EX500.
   Свеча-запчасть пересобирается под новую свечу (как в fixSpark выше). */
function fixExact(FIX) {
  /* свечи выбираем из ~27 тысяч деталей один раз на вызов, а не на каждый мотор */
  var sparks = PARTS.filter(function (p) { return p.kind === "spark"; }), own = {};
  sparks.forEach(function (p) { if (!own[p.id]) own[p.id] = p; });
  Object.keys(FIX).forEach(function (id) {
    var e = ENGINES[id], f = FIX[id];
    if (!e) return;
    Object.keys(f).forEach(function (k) { e[k] = f[k]; });
    if (!f.spark) return;
    sparks.forEach(function (p) { if (p.fit && p.fit.indexOf(id) >= 0 && p.id !== id + "-spark") p.fit = p.fit.filter(function (x) { return x !== id; }); });
    var mine = own[id + "-spark"];
    if (!mine) {
      if (ensureSpark.has) delete ensureSpark.has[id];
      ensureSpark(id, 1);
      mine = PARTS.find(function (p) { return p.id === id + "-spark"; });
      if (mine) { sparks.push(mine); own[mine.id] = mine; }
    }
    if (mine) mine.name = "Свеча " + f.spark.split(" (")[0].split(" /")[0].split(" +")[0].split(" ×")[0];
  });
}
